import { definePmNodeConverter } from './../../pm-converters/types.js';
import { removeNullValues } from './../../pm-converters/utils.js';
import type { ParagraphNode, TextNode } from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';
import type { PmNode, PmParagraphNode } from './../../_shared/pm-node-types.js';

export const paragraphConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.PARAGRAPH],
    convert: (node, visit) => {
      const { id = '', style, paragraphData } = node || {};

      const result: PmParagraphNode = {
        type: Node_Type.PARAGRAPH,
        attrs: {
          id,
          style: style ?? null,
          indentation: paragraphData?.indentation ?? null,
          level: paragraphData?.level ?? null,
          textStyle: paragraphData?.textStyle ?? null,
          animation: paragraphData?.animation ?? null,
        },
        content: (visit?.(node) ?? []) as PmNode[],
      };

      return result;
    },
  },
  fromPm: {
    types: [Node_Type.PARAGRAPH],
    convert: (node, visit) => {
      const attributes = (node as PmParagraphNode).attrs;
      const { id, style, ...data } = attributes || {};

      const nodes = (visit?.(node) ?? []) as TextNode[];
      const result: ParagraphNode = {
        type: Node_Type.PARAGRAPH,
        id,
        ...(nodes && nodes.length ? { nodes } : {}),
        ...(style ? { style } : {}),
        paragraphData: {
          ...removeNullValues(data),
        },
      };
      return result;
    },
  },
});
