import type { KeyboardShortcutCommand } from './../../tiptap/index.js';
import { createRicosFunctionalExtension } from './../../plugin-commons/index.js';

import type { ActionItemCallback, HistoryOptions } from './history-infra.js';
import { closeHistory, history, pushActionItem, redo, undo } from './history-infra.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    ricosHistory: {
      /**
       * Toggle a paragraph
       */
      rebase: (count: number) => ReturnType;
      silent: () => ReturnType;
      closeHistory: () => ReturnType;
      redo: () => ReturnType;
      undo: () => ReturnType;
      /**
       * Push an action item to the undo stack. When undo reaches this point,
       * the callback will be executed instead of normal undo behavior.
       */
      pushActionItem: (callback: ActionItemCallback) => ReturnType;
    };
  }
}

export const undoRedo = createRicosFunctionalExtension({
  type: 'extension',
  groups: ['shortcuts-enabled'],
  name: 'ricosHistory',
  createExtensionConfig({ services }) {
    const historySettings = services.editorProps.historySettings;
    const keyboardShortcuts = historySettings?.keyboardShortcuts;

    return {
      name: this.name,
      priority: 1000,
      addOptions: () => ({
        depth: 100,
        newGroupDelay: 500,
        onHistoryChange: historySettings?.onHistoryChange,
      }),
      addCommands() {
        return {
          rebase:
            count =>
            ({ tr }) => {
              tr.setMeta('rebased', count);
              return true;
            },
          silent:
            () =>
            ({ tr }) => {
              tr.setMeta('skip', true);
              return true;
            },
          closeHistory:
            () =>
            ({ tr }) => {
              closeHistory(tr);
              return true;
            },
          undo:
            () =>
            ({ state, dispatch }) => {
              return undo(state, dispatch);
            },
          redo:
            () =>
            ({ state, dispatch }) => {
              return redo(state, dispatch);
            },
          pushActionItem:
            (callback: ActionItemCallback) =>
            ({ state, dispatch }) => {
              if (!dispatch) {
                return false;
              }
              return pushActionItem(state, dispatch, callback);
            },
        };
      },
      addProseMirrorPlugins() {
        return [history(this.options as HistoryOptions)];
      },
      addKeyboardShortcuts() {
        // Keyboard shortcuts disabled entirely
        if (keyboardShortcuts === false) {
          return {} as { [key: string]: KeyboardShortcutCommand };
        }

        const undoHandler = keyboardShortcuts?.undo
          ? () => keyboardShortcuts.undo!()
          : () => this.editor.commands.undo();

        const redoHandler = keyboardShortcuts?.redo
          ? () => keyboardShortcuts.redo!()
          : () => this.editor.commands.redo();

        return {
          'Mod-z': undoHandler,
          'Mod-y': redoHandler,
          'Shift-Mod-z': redoHandler,
        };
      },
    };
  },
});
