import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { EditorState } from './../../tiptap/pm/state.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';

import { findParentList } from '../list-item/commands/commons.js';

/**
 * Keeps a list item's `checked` attribute faithful to checkbox-list membership.
 *
 * `checked` is the source of truth that `renderHTML` uses to mark an `<li>` as a
 * semantic checkbox (`role="checkbox"` + `aria-checked`) — including in the copied
 * clipboard HTML, where view decorations are not serialized. When a checkbox list is
 * converted to another list type, its items keep their stale `checked` attribute,
 * which would otherwise leak a spurious `role="checkbox"` onto plain bullet/ordered
 * items. This plugin clears `checked` on any list item that is no longer directly
 * inside a checkbox list.
 */
export const createCheckboxStateNormalizingTransactionPlugin = () =>
  new Plugin({
    key: new PluginKey('normalize-checkbox-state'),
    appendTransaction: (_, oldState: EditorState, newState: EditorState) => {
      if (newState.doc === oldState.doc) {
        return;
      }

      const tr = newState.tr;
      let changed = false;

      newState.doc.descendants((node, pos) => {
        if (node.type.name !== Node_Type.LIST_ITEM || node.attrs.checked === null) {
          return;
        }

        const parentList = findParentList(newState.doc.resolve(pos));
        if (!parentList || parentList.node.type.name !== Node_Type.CHECKBOX_LIST) {
          tr.setNodeAttribute(pos, 'checked', null);
          changed = true;
        }
      });

      return changed ? tr : undefined;
    },
  });
