import type { Decoration } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { isStrikethroughBlockedByCheckboxListSelection } from './../../_shared/list-checkbox/is-strikethrough-blocked-by-checkbox-list-selection.js';
import { isMarkActive } from './../../tiptap/index.js';
import { markInputRule, markPasteRule } from './../../tiptap/core/index.js';
import { createRicosMarkExtension } from './../../plugin-commons/index.js';
import { getStylesDecorationBySelectedNode } from './../../tiptap-extensions/index.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    strikethrough: {
      /**
       * Set a strikethrough mark
       */
      setStrikethrough: () => ReturnType;
      /**
       * Toggle a strikethrough mark
       */
      toggleStrikethrough: () => ReturnType;
      /**
       * Unset a strikethrough mark
       */
      unsetStrikethrough: () => ReturnType;
    };
  }
}

const name = Decoration_Type.STRIKETHROUGH;

export const inputRegex = /(?:^|\s)(~~(?!\s+~~)((?:[^~]+))~~(?!\s+~~))$/;
export const pasteRegex = /(?:^|\s)(~~(?!\s+~~)((?:[^~]+))~~(?!\s+~~))/g;

export const strikethrough = createRicosMarkExtension<{
  HTMLAttributes: Record<string, string>;
}>({
  type: 'mark',
  groups: [],
  name,
  reconfigure(config, _extensions, _ricosProps, _settings, services) {
    return {
      ...config,
      addCommands() {
        return {
          setStrikethrough:
            () =>
            ({ commands, state }) => {
              if (isStrikethroughBlockedByCheckboxListSelection(state)) {
                return false;
              }

              return commands.setMark(this.name);
            },
          toggleStrikethrough:
            () =>
            ({ commands, state }) => {
              if (isStrikethroughBlockedByCheckboxListSelection(state)) {
                return false;
              }

              const decoration: Decoration | undefined = getStylesDecorationBySelectedNode(name, {
                state,
                styles: services.styles,
                pmConverters: services.converters,
              });
              const hasStrikethroughInStyle = decoration && decoration.strikethroughData === true;
              const hasStrikethroughInMark = isMarkActive(state, this.name, {
                strikethroughData: true,
              });

              return commands.toggleMark(this.name, {
                strikethroughData: !!(hasStrikethroughInMark || !hasStrikethroughInStyle),
              });
            },
          unsetStrikethrough:
            () =>
            ({ commands, state }) => {
              if (isStrikethroughBlockedByCheckboxListSelection(state)) {
                return false;
              }

              return commands.unsetMark(this.name);
            },
        };
      },
    };
  },
  createExtensionConfig() {
    return {
      name,

      addOptions() {
        return {
          HTMLAttributes: {},
        };
      },

      addAttributes() {
        return {
          strikethroughData: {
            default: true,
          },
        };
      },

      parseHTML() {
        return [
          {
            tag: 's',
          },
          {
            tag: 'del',
          },
          {
            tag: 'strike',
          },
          {
            style: 'text-decoration',
            consuming: false,
            getAttrs: style => (style.includes('line-through') ? {} : false),
          },
        ];
      },

      renderHTML({ HTMLAttributes }) {
        const { strikethroughData } = HTMLAttributes;
        return [
          's',
          {
            style: `text-decoration: ${strikethroughData ? 'line-through' : 'none'}`,
          },
          0,
        ];
      },

      addKeyboardShortcuts() {
        return {
          'Mod-Shift-x': () => this.editor.commands.toggleStrikethrough(),
        };
      },

      addInputRules() {
        return [
          markInputRule({
            find: inputRegex,
            type: this.type,
          }),
        ];
      },

      addPasteRules() {
        return [
          markPasteRule({
            find: pasteRegex,
            type: this.type,
          }),
        ];
      },
    };
  },
});
