import { definePmNodeConverter } from './../../pm-converters/types.js';
import { stripCheckedFromListItemNodes } from './../../ricos-common-plugins/list-item/strip-checked-from-list-item-nodes.js';
import type { BulletedListData } from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';

const bulletedListDataDefaults = { indentation: 0, offset: 0 } as const;
export const bulletedListConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.BULLETED_LIST],
    convert: (node, visit) => {
      const dataWithDefaults = (
        Object.entries(bulletedListDataDefaults) as [
          keyof typeof bulletedListDataDefaults,
          number,
        ][]
      ).reduce((acc, [key, defaultValue]) => {
        acc[key] = node.bulletedListData?.[key] ?? defaultValue;
        return acc;
      }, {} as BulletedListData);
      return {
        type: Node_Type.BULLETED_LIST,
        attrs: {
          ...dataWithDefaults,
          id: node.id,
          animation: node.bulletedListData?.animation ?? null,
        },
        content: visit?.(node),
      };
    },
  },
  fromPm: {
    types: [Node_Type.BULLETED_LIST],
    convert: (node, visit) => {
      const { attrs = {} } = node;
      const { id, animation, ...data } = attrs;
      return {
        type: Node_Type.BULLETED_LIST,
        id,
        nodes: stripCheckedFromListItemNodes(visit?.(node) ?? []),
        bulletedListData: {
          ...(Object.keys(data) as (keyof typeof bulletedListDataDefaults)[]).reduce((acc, key) => {
            if (data[key] !== bulletedListDataDefaults[key]) {
              acc[key] = data[key];
            }
            return acc;
          }, {} as BulletedListData),
          ...(animation ? { animation } : {}),
        },
      };
    },
  },
});
