import { definePmNodeConverter } from './../../pm-converters/types.js';
import { stripCheckedFromListItemNodes } from './../../ricos-common-plugins/list-item/strip-checked-from-list-item-nodes.js';
import type { OrderedListData } from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';

const orderedListDataDefaults = {
  indentation: 0,
  offset: 0,
  start: 1,
} as const;
export const orderedListConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.ORDERED_LIST],
    convert: (node, visit) => {
      const dataWithDefaults = {
        indentation: node.orderedListData?.indentation ?? orderedListDataDefaults.indentation,
        offset: node.orderedListData?.offset ?? orderedListDataDefaults.offset,
        start: node.orderedListData?.start ?? orderedListDataDefaults.start,
      };

      return {
        type: Node_Type.ORDERED_LIST,
        attrs: {
          ...dataWithDefaults,
          id: node.id,
          animation: node.orderedListData?.animation ?? null,
        },
        content: visit?.(node) ?? [],
      };
    },
  },

  fromPm: {
    types: [Node_Type.ORDERED_LIST],
    convert: (node, visit?) => {
      const { id, animation, ...data } = node.attrs || {};

      return {
        type: Node_Type.ORDERED_LIST,
        id,
        nodes: stripCheckedFromListItemNodes(visit?.(node) ?? []),
        orderedListData: {
          ...(Object.keys(data) as (keyof typeof orderedListDataDefaults)[]).reduce((acc, key) => {
            if (data[key] !== orderedListDataDefaults[key]) {
              acc[key] = data[key];
            }
            return acc;
          }, {} as OrderedListData),
          ...(animation ? { animation } : {}),
        },
      };
    },
  },
});
