import React from 'react';

import { UNSUPPORTED_NODE_TYPE } from './../../pm-converters/consts.js';
import { RicosContext } from './../../ricos-context/ricos-context.js';
import type { PluginProps } from './../../ricos-types/index.js';
import { GenericError } from './../../ui-components/Components/generic-error.js';
import { createRicosNodeExtension } from './../../tiptap-extensions/index.js';

export const UnsupportedBlock: React.FC<PluginProps> = () => {
  const { t } = React.useContext(RicosContext);
  return (
    <div contentEditable={false}>
      <GenericError text={t('UnsupportedPlugin_message')} />
    </div>
  );
};

export const unsupportedNode = createRicosNodeExtension<{
  HTMLAttributes: Record<string, unknown>;
}>({
  groups: ['draggable', 'not-overtypable', 'no-trailing-node'],
  type: 'react-node',
  Component: UnsupportedBlock,
  name: UNSUPPORTED_NODE_TYPE,
  createExtensionConfig: () => ({
    name: UNSUPPORTED_NODE_TYPE,
    addAttributes() {
      return {
        originalNode: {},
      };
    },
    group:
      'block smartBlockCellContent layoutCellContent collapsibleListItemTitleContent collapsibleListItemBodyContent tableCellContent listItemFirstChildContent listItemSecondChildContent figureFirstChildContent figureSecondChildContent',
    selectable: true,
    allowGapCursor: false,
  }),
});
