import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { getNodeType, isNodeActive, mergeAttributes } from './../../tiptap/index.js';
import { InputRule } from './../../tiptap/core/index.js';
import type { DOMOutputSpec } from './../../tiptap/pm/model.js';
import {
  createRicosNodeExtension,
  withBreakoutContainer,
} from './../../plugin-commons/index.js';

import { createListInputRuleHandler } from '../list-input-rule-handler.js';
import styles from '../statics/styles-scss.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    orderedList: {
      /**
       * Toggle an ordered list
       */
      toggleOrderedList: () => ReturnType;
      /**
       * Toggle off an ordered list if exists
       */
      toggleOffOrderedList: () => ReturnType;
    };
  }
}

const inputRegex = /^(\d+)\.\s$/;

export const orderedList = createRicosNodeExtension<{
  itemTypeName: string;
  HTMLAttributes: Record<string, string>;
}>({
  groups: ['no-trailing-node'],
  type: 'html-node',
  name: Node_Type.ORDERED_LIST,
  createExtensionConfig() {
    return {
      name: this.name,
      addOptions() {
        return {
          itemTypeName: Node_Type.LIST_ITEM,
          HTMLAttributes: { class: styles.orderedList },
        };
      },

      group:
        'block list listItemSecondChildContent smartBlockCellContent layoutCellContent collapsibleListItemTitleContent collapsibleListItemBodyContent tableCellContent',
      // group 'list' needed for tiptap's `isList` method to work.

      content() {
        return 'LIST_ITEM+';
      },

      addAttributes() {
        return {
          indentation: { default: 0 },
          offset: { default: 0 },
          start: { default: 1 },
        };
      },

      parseHTML() {
        return [
          {
            tag: 'ol',
          },
        ];
      },

      renderHTML({ HTMLAttributes }) {
        return withBreakoutContainer([
          'ol',
          mergeAttributes(this.options.HTMLAttributes, HTMLAttributes),
          0,
        ]) as DOMOutputSpec;
      },

      addCommands() {
        return {
          toggleOrderedList:
            () =>
            ({ commands }) => {
              return commands.toggleLists(this.name, this.options.itemTypeName);
            },
          toggleOffOrderedList:
            () =>
            ({ state, commands }) => {
              const isActive = isNodeActive(state, getNodeType(this.name, state.schema));
              if (isActive) {
                return commands.toggleOrderedList();
              }
              return true;
            },
        };
      },

      addKeyboardShortcuts() {
        return {
          'Mod-Shift-7': () => this.editor.commands.toggleOrderedList(),
        };
      },

      addInputRules() {
        const getAttributes = (match: $TSFixMe) => ({
          start: Number(match[1]),
        });
        const joinPredicate = (match: $TSFixMe, node: $TSFixMe) =>
          node.childCount + node.attrs.start === Number(match[1]);

        return [
          new InputRule({
            find: inputRegex,
            handler: createListInputRuleHandler({ type: this.type, getAttributes, joinPredicate }),
          }),
        ];
      },
    };
  },
});
