import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { getNodeType, isNodeActive } from './../../tiptap/index.js';
import { InputRule } from './../../tiptap/core/index.js';
import type { DOMOutputSpec } from './../../tiptap/pm/model.js';
import {
  createRicosNodeExtension,
  withBreakoutContainer,
} from './../../plugin-commons/index.js';

import { createListInputRuleHandler } from '../list-input-rule-handler.js';
import styles from '../statics/styles-scss.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    bulletList: {
      /**
       * Toggle a bullet list
       */
      toggleBulletList: () => ReturnType;
      /**
       * Toggle off an bulleted list if exists
       */
      toggleOffBulletList: () => ReturnType;
    };
  }
}

const inputRegex = /^\s*([-+*])\s$/;

export const bulletedList = createRicosNodeExtension<{
  HTMLAttributes: Record<string, string>;
  itemTypeName: string;
}>({
  groups: ['no-trailing-node'],
  type: 'html-node',
  name: Node_Type.BULLETED_LIST,
  createExtensionConfig({ mergeAttributes }) {
    return {
      name: this.name,
      addOptions() {
        return {
          HTMLAttributes: { class: styles.bulletedList },
          itemTypeName: Node_Type.LIST_ITEM,
        };
      },

      group:
        'block list listItemSecondChildContent smartBlockCellContent layoutCellContent collapsibleListItemTitleContent collapsibleListItemBodyContent tableCellContent',
      // group 'list' needed for tiptap's `isList` method to work.

      content() {
        return 'LIST_ITEM+';
      },

      parseHTML() {
        return [{ tag: 'ul' }];
      },

      addAttributes() {
        return {
          indentation: {
            default: 0,
          },
          offset: {
            default: 0,
          },
        };
      },

      renderHTML({ HTMLAttributes }) {
        return withBreakoutContainer([
          'ul',
          mergeAttributes(this.options.HTMLAttributes, HTMLAttributes),
          0,
        ]) as DOMOutputSpec;
      },

      addCommands() {
        return {
          toggleBulletList:
            () =>
            ({ commands }) => {
              return commands.toggleLists(this.name, Node_Type.LIST_ITEM);
            },
          toggleOffBulletList:
            () =>
            ({ state, commands }) => {
              const isActive = isNodeActive(state, getNodeType(this.name, state.schema));
              if (isActive) {
                return commands.toggleBulletList();
              }
              return true;
            },
        };
      },

      addKeyboardShortcuts() {
        return {
          'Mod-Shift-8': () => this.editor.commands.toggleBulletList(),
        };
      },

      addInputRules() {
        return [
          new InputRule({
            find: inputRegex,
            handler: createListInputRuleHandler({ type: this.type }),
          }),
        ];
      },
    };
  },
});
