import { definePmNodeConverter } from './../../pm-converters/types.js';
import blockquoteDefaultData from './../../ricos-schema/legacy/statics/blockquote.defaults.json.js';
import type { ParagraphData, ParagraphNode, TextNode } from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';

type ParagraphFields = {
  paragraphData: ParagraphData;
  paragraphId: string;
};

const toParagraphFields = (node: ParagraphNode): ParagraphFields => {
  const { id: paragraphId, paragraphData = {} } = node;
  return { paragraphData, paragraphId } as ParagraphFields;
};

const toParagraphNode =
  (fields: ParagraphFields) =>
  (nodes: TextNode[]): ParagraphNode => {
    return {
      id: fields.paragraphId,
      type: Node_Type.PARAGRAPH,
      paragraphData: fields.paragraphData,
      nodes,
    };
  };

export const blockquoteConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.BLOCKQUOTE],
    convert: (node, visit) => {
      const { id, style, blockquoteData } = node || {};
      const firstNode = (node.nodes?.[0] ??
        ({ id: '', paragraphData: {} } as ParagraphNode)) as ParagraphNode;
      const { paragraphData, paragraphId } = toParagraphFields(firstNode);
      return {
        type: Node_Type.BLOCKQUOTE,
        attrs: {
          paragraphId,
          textStyle: paragraphData.textStyle,
          indentation: blockquoteData?.indentation ?? blockquoteDefaultData.indentation,
          ...(style ? { style } : {}),
          id,
          animation: blockquoteData?.animation ?? null,
        },
        // skip internal paragraph, go to text nodes
        content: node.nodes?.[0] ? (visit?.(node.nodes[0]) ?? []) : [],
      };
    },
  },
  fromPm: {
    types: [Node_Type.BLOCKQUOTE],
    convert: (node, visit?) => {
      const { id, style, paragraphId, textStyle, indentation, animation } = node.attrs || {};
      const paragraphNode = toParagraphNode({
        paragraphData: { indentation: 0, textStyle },
        paragraphId,
      })((visit?.(node) ?? []) as TextNode[]);
      return {
        type: Node_Type.BLOCKQUOTE,
        id,
        nodes: [paragraphNode],
        ...(style ? { style } : {}),
        blockquoteData: {
          indentation,
          ...(animation ? { animation } : {}),
        },
      };
    },
  },
});
