import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Mark_Type } from './../../ricos-types/index.js';
import { getBlockDefaultFontSize } from './../../_shared/list-checkbox/get-block-default-font-size.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';

import type { Level } from '../title/extension.js';
import { HEADER_NAMES } from '../title/header-names.js';
import { onlyChangesUnrelatedAttrs } from '../transaction-predicates/only-changes-unrelated-attrs.js';

// Reads heading `attrs.level` on the list item's first child. Marks (font-
// size) come through `Add/RemoveMarkStep` — non-attr — and correctly
// defeat the predicate without needing to be listed here.
const RELEVANT_ATTRS: ReadonlySet<string> = new Set(['level']);

/**
 * Adds, depending on the list item's first child:
 * - a font-size (so the list marker and paddings size with the first text node),
 * - a `data-child-font-fit` flag when that font-size is smaller than the block's
 *   own default, so the child paragraph/heading shrinks its font to match (see
 *   `list-checkbox.scss`),
 * - and/or a `data-heading-level` attribute (so a heading-first list item gets
 *   heading styles).
 *
 * No `reuseWhen`: the decoration value depends on the first child's first
 * text node's marks / type, which inline-text edits can change (pasting
 * marked text in front of an unmarked first character, typing that changes
 * the first mark, etc.). Cache is still used across selection-only
 * transactions.
 */
export const createListItemSizingDecorationPlugin = () => {
  const key = new PluginKey<DecorationSet>('list-item-sizing');

  return new Plugin<DecorationSet>({
    key,
    state: {
      init: (_config, state) => buildListItemSizingDecorations(state.doc),
      // No `reuseWhen` predicate — see plugin docstring for why.
      apply: (tr, prev) => {
        if (!tr.docChanged) {
          return prev;
        }
        if (onlyChangesUnrelatedAttrs(tr, RELEVANT_ATTRS)) {
          return prev;
        }
        return buildListItemSizingDecorations(tr.doc);
      },
    },
    props: {
      decorations(state) {
        return key.getState(state);
      },
    },
  });
};

const buildListItemSizingDecorations = (doc: ProseMirrorNode): DecorationSet => {
  const decorations: Decoration[] = [];

  doc.descendants((node, pos) => {
    // Text blocks (paragraph, heading, blockquote) cannot contain list items,
    // so skipping their subtree avoids visiting every text/mark node.
    // We cannot prune at LIST_ITEM because it may contain nested lists via
    // `listItemSecondChildContent`, and those nested list items still need
    // decorations.
    if (node.isTextblock) {
      return false;
    }

    if (node.type.name !== Node_Type.LIST_ITEM) {
      return;
    }

    const firstChildOfListItem = node.firstChild;
    const headingLevel: Level | undefined =
      firstChildOfListItem?.type.name === Node_Type.HEADING
        ? firstChildOfListItem?.attrs.level || 1
        : undefined;

    // If the list item's child's (paragraph's/heading's) first text node has
    // a specified font-size, apply it to the list item as a decoration so the
    // list marker matches the text font-size.
    const childFontSize = Number(
      firstChildOfListItem?.firstChild?.marks.find(mark => mark.type.name === Mark_Type.FONT_SIZE)
        ?.attrs.value
    );
    if (childFontSize) {
      decorations.push(
        Decoration.node(pos, pos + node.nodeSize, {
          style: `font-size: ${childFontSize}px;`,
          // When the chosen font is smaller than the block's own default, the
          // block's strut keeps the line (and marker) oversized; flag the item
          // so the child paragraph/heading shrinks its font to match — see
          // `list-checkbox.scss`.
          ...(childFontSize < getBlockDefaultFontSize(headingLevel)
            ? { 'data-child-font-fit': 'true' }
            : {}),
        })
      );
    }

    if (headingLevel !== undefined) {
      decorations.push(
        Decoration.node(pos, pos + node.nodeSize, {
          'data-heading-level': `header${HEADER_NAMES[headingLevel - 1]}`,
        })
      );
    }
  });

  return DecorationSet.create(doc, decorations);
};
