import type { ModalService } from './../../../ricos-modals/index.js';

import { QuickActionsModal } from '../modal/modal.js';
import { QUICK_ACTIONS_MODAL_ID } from '../types.js';

export type toggleQuickActionsModalProps = {
  modalService: ModalService;
  referenceElement: HTMLDivElement | HTMLButtonElement | null;
  isMobile: boolean;
  supportedPlugins?: string[];
};

export const toggleQuickActionsModal = (props: toggleQuickActionsModalProps) => {
  const { modalService, referenceElement, supportedPlugins } = props;
  modalService.isModalOpen(QUICK_ACTIONS_MODAL_ID)
    ? modalService.closeModal(QUICK_ACTIONS_MODAL_ID)
    : modalService.openModal({
        id: QUICK_ACTIONS_MODAL_ID,
        Component: QuickActionsModal,
        componentProps: { supportedPlugins },
        layout: {
          desktop: 'floating',
          mobile: 'drawer',
        },
        onClickOutside: {
          on: 'pointerdown',
          handler: (e: PointerEvent) => {
            const isToggleButton =
              e.target === referenceElement || referenceElement?.contains(e.target as Node);
            if (isToggleButton) {
              return;
            }
            modalService.closeModal(QUICK_ACTIONS_MODAL_ID);
          },
        } as { on: 'pointerdown'; handler: (e: PointerEvent) => void },
        positioning: {
          referenceElement,
          placement: props.isMobile ? 'bottom' : 'bottom-start',
        },
        autoFocus: true,
        type: 'exclusive',
      });
};
