import { Node_Type } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { NodeWithPos } from './../../../tiptap/index.js';
import type { Node } from './../../../tiptap/pm/model.js';
import type { Transaction } from './../../../tiptap/pm/state.js';

import type { ChangeListChildrenIndent } from './commons.js';
import {
  changeIndentationOfEveryListSeparately,
  changeIndentationOfNotSelectedNodes,
  findParentList,
  getIndentationsInSelection,
  getListItemsInSelection,
  getNotSelectedDescendantListItems,
} from './commons.js';
import { sinkListItemNodes } from './indent-list.js';
import { lifListItemNodes } from './lift-list-item-nodes.js';

export const outdentList =
  () =>
  ({ tr }: $TSFixMe) => {
    const { smallestIndentation } = getIndentationsInSelection(tr);
    if (smallestIndentation === 0) {
      return false;
    }
    return liftListItem(tr);
  };

const liftListItem = (tr: Transaction) => {
  const parentList = findParentList(tr.selection.$from);
  if (!parentList) {
    return false;
  }

  const multipleListsInSelection = tr.selection.to > parentList.pos + parentList.node.nodeSize;

  if (multipleListsInSelection) {
    changeIndentationOfEveryListSeparately(tr, liftChildrenOfList);
    return true;
  }

  liftChildrenOfList(tr, parentList);
  return true;
};

const liftChildrenOfList: ChangeListChildrenIndent = (tr, parentList) => {
  const selectedListItems = getListItemsInSelection(tr, parentList);
  const areListItemsLiftedSemantically = lifListItemNodes(tr, selectedListItems, parentList);

  if (!areListItemsLiftedSemantically) {
    // this affects the list parent so other sibling list items that are in the same parent but are not in selection need to be sunk
    const notSelectedSiblingListItems = getNotSelectedSiblingListItems(tr, parentList);
    changeIndentationOfNotSelectedNodes(tr, notSelectedSiblingListItems, sinkListItemNodes);
  }
  // we always need to sink children list items that are not in selection of lifted list items
  const notSelectedDescendantListItems = getNotSelectedDescendantListItems(tr, selectedListItems);
  changeIndentationOfNotSelectedNodes(tr, notSelectedDescendantListItems, sinkListItemNodes);

  return selectedListItems;
};

const getNotSelectedSiblingListItems = (tr: Transaction, parentList: NodeWithPos) => {
  const notSelectedSiblingListItems: NodeWithPos[] = [];

  parentList.node.descendants((childNode: Node, childPos: number) => {
    const childPosInDoc = childPos + parentList.pos + 1;
    if (childNode.type.name !== Node_Type.LIST_ITEM || childPosInDoc < tr.selection.to) {
      return false;
    }
    notSelectedSiblingListItems.push({ node: childNode, pos: childPosInDoc });
  });

  return notSelectedSiblingListItems;
};
