import type { PmMarkConverter } from './../../pm-converters/types.js';
import type { FontSizeDecoration } from './../../ricos-schema/next-schema/index.js';
import { Decoration_Type } from './../../ricos-schema/next-schema/index.js';

export const fontSizeConverter: PmMarkConverter = {
  fromPm: {
    type: Decoration_Type.FONT_SIZE,
    convert: mark => {
      const { attrs } = mark;
      if (!attrs || !attrs.value) {
        return [];
      }
      return [
        {
          type: Decoration_Type.FONT_SIZE,
          fontSizeData: {
            value: attrs.value,
            // if attrs.unit is 'PX' we should not save it since it defaults to that anyway,
            // but old versions of viewer will be angry if it's not there, so we keep it for now
            unit: attrs.unit ?? 'PX',
          },
        } satisfies FontSizeDecoration,
      ];
    },
  },
  toPm: {
    type: Decoration_Type.FONT_SIZE,
    convert: decoration => {
      const { fontSizeData } = decoration as FontSizeDecoration;
      if (!fontSizeData || !fontSizeData.value) {
        return undefined;
      }
      return {
        type: Decoration_Type.FONT_SIZE,
        attrs: {
          value: fontSizeData.value,
          unit: fontSizeData.unit ?? 'PX',
        },
      };
    },
  },
};
