import type { RicosExtensionConfig } from './../../ricos-types/index.js';
import { createRicosFunctionalExtension } from './../../tiptap-extensions/index.js';

import { isNodeSpaced } from './gap-spacer-nodes.js';
import { gapSpacer } from './gap-spacer-plugin.js';

export const gapSpacerExtension = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'gapSpacer',
  reconfigure(config: RicosExtensionConfig, _extensions, _props, _settings, services) {
    return {
      ...config,
      addOptions() {
        return {
          t: services.t,
        };
      },
    };
  },
  createExtensionConfig() {
    return {
      name: this.name,

      addProseMirrorPlugins() {
        return [gapSpacer(this.options.t)];
      },
      extendNodeSchema(extension) {
        const allowGapSpacer = isNodeSpaced(extension.name);

        return {
          allowGapSpacer,
        };
      },
    };
  },
});
