import type { ListItemNode, Node } from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';

export const stripCheckedFromListItemNodes = <T extends Node>(nodes: T[]): T[] =>
  nodes.map(node => {
    if (node.type !== Node_Type.LIST_ITEM || !node.listItemData) {
      return node;
    }
    const { listItemData, ...rest } = node as ListItemNode;
    // `checked` is only meaningful in checkbox lists; other fields (animation) stay
    const { checked: _checked, ...restData } = listItemData ?? {};
    return (Object.keys(restData).length > 0 ? { ...rest, listItemData: restData } : rest) as T;
  });
