import { Italic } from '@wix/wix-ui-icons-common/lazy';

import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { EditorPlugin } from './../../ricos-types/index.js';
import { createShortcut } from './../../ricos-types/index.js';
import { isAlwaysVisible } from './../../_shared/resolvers/is-always-visible.js';
import { isItalicInText } from './../../_shared/resolvers/is-italic-in-text.js';
import { isNodeSelected } from './../../_shared/resolvers/is-node-selected.js';

import { TEXT_BUTTON_ITALIC } from './data-hooks.js';
import { italic } from './extension.js';
import { italicConverter } from './italic-converter.js';

export const pluginItalic: EditorPlugin = {
  type: Decoration_Type.ITALIC,
  config: {},
  pmNodeConverters: [],
  pmMarkConverters: [italicConverter],
  tiptapExtensions: [italic],
  shortcuts: [
    createShortcut({
      name: Decoration_Type.ITALIC,
      description: 'ShortcutsSheet_Formatting_Italic',
      keys: { macOs: 'Meta+I', windows: 'Ctrl+I' },
      command({ publicCommands }) {
        publicCommands.toggleInlineStyle('italic');
        return 'continue';
      },
      group: 'ShortcutsSheet_Section_Formatting',
      enabled: true,
      showInShortcutSheet: true,
    }),
  ],
  textButtons: [
    {
      id: Decoration_Type.ITALIC,
      type: 'toggle',
      presentation: {
        dataHook: TEXT_BUTTON_ITALIC,
        tooltip: 'ItalicButton_Tooltip',
        icon: Italic,
      },
      attributes: {
        visible: isAlwaysVisible,
        active: isItalicInText,
        disabled: isNodeSelected,
      },
      command:
        ({ publicCommands }) =>
        () => {
          publicCommands.toggleInlineStyle('italic');
          return true;
        },
    },
  ],
};
