import type { ExtensionProps, RicosExtension, RicosExtensionConfig } from './../../ricos-types/index.js';
import { DraggableHOC } from './../../_shared/draggable-hoc.js';
import { createRicosFunctionalExtension } from './../../plugin-commons/index.js';

export const draggable = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'ricos-draggable',
  reconfigure(
    config: RicosExtensionConfig,
    extensions: RicosExtension[],
    _ricosProps: ExtensionProps
  ) {
    const types = extensions
      .filter(extension => extension.groups.includes('draggable'))
      .map(({ name }) => name);

    return {
      ...config,
      priority: 70,
      addNodeHoc: () => {
        return {
          nodeTypes: types,
          getNodeHoc: () => DraggableHOC,
          priority: 70,
        };
      },
    };
  },
  createExtensionConfig() {
    return {
      name: this.name,
    };
  },
});
