import type { PmMarkConverter } from './../../pm-converters/types.js';
import type { StrikethroughDecoration } from './../../ricos-schema/next-schema/index.js';
import { Decoration_Type } from './../../ricos-schema/next-schema/index.js';

export const strikethroughConverter: PmMarkConverter = {
  fromPm: {
    type: Decoration_Type.STRIKETHROUGH,
    convert: mark => {
      const { type: _, attrs } = mark;

      if (typeof attrs?.strikethroughData === 'undefined' || attrs.strikethroughData) {
        return [{ type: Decoration_Type.STRIKETHROUGH }];
      }

      return [{ type: Decoration_Type.STRIKETHROUGH, ...attrs }];
    },
  },
  toPm: {
    type: Decoration_Type.STRIKETHROUGH,
    convert: decoration => {
      const { type: _, ...data } = decoration as StrikethroughDecoration;

      if (typeof data.strikethroughData === 'undefined') {
        return {
          type: Decoration_Type.STRIKETHROUGH,
          attrs: { strikethroughData: true },
        };
      }

      return {
        type: Decoration_Type.STRIKETHROUGH,
        attrs: { ...data },
      };
    },
  },
};
