import type { TFunction } from './../../ricos-types/index.js';
import { keydownHandler } from './../../tiptap/pm/keymap.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import { Fragment, Slice } from './../../tiptap/pm/model.js';
import type { Command, EditorState, Transaction } from './../../tiptap/pm/state.js';
import { Plugin, PluginKey, TextSelection } from './../../tiptap/pm/state.js';
import type { EditorView } from './../../tiptap/pm/view.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';

import { isInlineTextOnly } from '../transaction-predicates/is-inline-text-only.js';
import { onlyChangesUnrelatedAttrs } from '../transaction-predicates/only-changes-unrelated-attrs.js';
import { GapCursor } from './gap-cursor-selection.js';
import { createGapSpacerElement } from './gap-spacer-component/gap-spacer-html.js';
import styles from './gap-spacer-component/gap-spacer-styles-scss.js';
import {
  isBetweenFloatedNodes,
  isBetweenFullWidthNodes,
  isCollapsedBetween,
  needsTopMarginForPmNode,
} from './gap-spacer-nodes.js';

const gapSpacerPluginKey = new PluginKey('gap-spacer');

// Reads neighbour `attrs.containerData` (alignment, textWrap, width.size).
const RELEVANT_ATTRS: ReadonlySet<string> = new Set(['containerData']);

type GapSpacerPosition = {
  pos: number;
  collapsed: boolean;
  betweenFloated: boolean;
  needsTopMargin: boolean;
};

type GapSpacerPluginState = {
  positions: GapSpacerPosition[];
  decorations: DecorationSet | null;
  /**
   * `head` of the current selection when it is a `GapCursor`, otherwise `null`.
   * Tracked in plugin state so that selection-only transactions can reuse the
   * cached `DecorationSet` unless the focused gap spacer changed.
   */
  focusedPos: number | null;
};

const getFocusedPos = (state: EditorState): number | null =>
  state.selection instanceof GapCursor ? state.selection.head : null;

const collectGapPositions = (doc: ProseMirrorNode): number[] => {
  const positions: number[] = [];
  const seen: Set<number> = new Set();

  const addPosition = (pos: number): void => {
    if (!seen.has(pos)) {
      seen.add(pos);
      positions.push(pos);
    }
  };

  doc.descendants((node, pos) => {
    addPosition(pos);
    addPosition(pos + node.nodeSize);
  });

  return positions;
};

const computeGapSpacerPositions = (doc: ProseMirrorNode): GapSpacerPosition[] => {
  const positions: GapSpacerPosition[] = [];
  const candidatePositions: readonly number[] = collectGapPositions(doc);

  for (const pos of candidatePositions) {
    const $pos = doc.resolve(pos);

    if (!GapCursor.valid($pos)) {
      continue;
    }

    const bothFullWidth = isBetweenFullWidthNodes($pos.nodeBefore, $pos.nodeAfter);

    const collapsed = isCollapsedBetween(
      $pos.nodeBefore?.type.name,
      $pos.nodeAfter?.type.name,
      $pos.parent?.type.name,
      { bothFullWidth }
    );

    const betweenFloated = isBetweenFloatedNodes($pos.nodeBefore, $pos.nodeAfter);

    // First gap spacer (no nodeBefore) needs top margin if nodeAfter has top overflow
    const isFirstPosition = !$pos.nodeBefore && $pos.depth === 0;
    const hasTopOverflow = needsTopMarginForPmNode($pos.nodeAfter);

    positions.push({
      pos,
      collapsed,
      betweenFloated,
      needsTopMargin: isFirstPosition && hasTopOverflow,
    });
  }

  return positions;
};

export const gapSpacer = (t: TFunction): Plugin<GapSpacerPluginState> => {
  return new Plugin<GapSpacerPluginState>({
    key: gapSpacerPluginKey,
    state: {
      init: (_, state): GapSpacerPluginState => {
        const doc = state.doc as unknown as ProseMirrorNode;
        const positions = computeGapSpacerPositions(doc);
        const focusedPos = getFocusedPos(state);
        return {
          positions,
          focusedPos,
          decorations: buildGapSpacerDecorationSet({
            doc,
            t,
            positions,
            focusedPos,
          }),
        };
      },
      apply: (tr: Transaction, prev: GapSpacerPluginState, _oldState, newState) => {
        const newDoc = newState.doc as unknown as ProseMirrorNode;
        const newFocusedPos = getFocusedPos(newState);

        let nextPositions = prev.positions;
        let positionsChanged = false;

        if (tr.docChanged) {
          // Inline-text-only transactions cannot add, remove, split, merge,
          // wrap, or re-parent any block node — they only shift offsets inside
          // a single textblock. Every gap spacer's structural neighbours
          // (`$pos.nodeBefore`, `$pos.nodeAfter`, `$pos.parent`) and their
          // `attrs.containerData` are therefore invariant, so the cached
          // `collapsed` / `betweenFloated` / `needsTopMargin` values remain
          // correct — only the absolute `pos` needs remapping through
          // `tr.mapping`.
          if (isInlineTextOnly(tr)) {
            nextPositions = prev.positions.map(position => ({
              ...position,
              pos: tr.mapping.map(position.pos),
            }));
            positionsChanged = true;
          } else if (!onlyChangesUnrelatedAttrs(tr, RELEVANT_ATTRS)) {
            nextPositions = computeGapSpacerPositions(newDoc);
            positionsChanged = true;
          }
        }

        if (!positionsChanged && prev.focusedPos === newFocusedPos) {
          return prev;
        }

        return {
          positions: nextPositions,
          focusedPos: newFocusedPos,
          decorations: buildGapSpacerDecorationSet({
            doc: newDoc,
            t,
            positions: nextPositions,
            focusedPos: newFocusedPos,
          }),
        };
      },
    },
    props: {
      decorations: state => {
        const pluginState = gapSpacerPluginKey.getState(state) as GapSpacerPluginState | null;
        return pluginState?.decorations ?? null;
      },
      handleKeyDown,
      handleDOMEvents: {
        beforeinput,
      },
    },
  });
};

const arrow = (axis: 'vertical' | 'horizontal', dir: number): Command => {
  const direction = axis === 'vertical' ? (dir > 0 ? 'down' : 'up') : dir > 0 ? 'right' : 'left';
  return function (state, dispatch, view) {
    const sel = state.selection;
    let $start = dir > 0 ? sel.$to : sel.$from;
    let mustMove = sel.empty;

    if (sel instanceof TextSelection) {
      if (!view!.endOfTextblock(direction) || $start.depth === 0) {
        return false;
      }
      mustMove = false;
      $start = state.doc.resolve(dir > 0 ? $start.after() : $start.before());
    }

    const $found = GapCursor.findGapCursorFrom($start, dir, mustMove);
    if (!$found) {
      return false;
    }

    if (dispatch) {
      dispatch(state.tr.setSelection(new GapCursor($found)));
    }
    return true;
  };
};

const handleKeyDown = keydownHandler({
  ArrowLeft: arrow('horizontal', -1),
  ArrowRight: arrow('horizontal', 1),
  ArrowUp: arrow('vertical', -1),
  ArrowDown: arrow('vertical', 1),
});

// This is a hack that, when a composition starts while a gap cursor
// is active, quickly creates an inline context for the composition to
// happen in, to avoid it being aborted by the DOM selection being
// moved into a valid position.
const beforeinput = (view: EditorView, event: InputEvent) => {
  if (event.inputType !== 'insertCompositionText' || !(view.state.selection instanceof GapCursor)) {
    return false;
  }

  const { $from } = view.state.selection;
  const insert = $from.parent
    .contentMatchAt($from.index())
    .findWrapping(view.state.schema.nodes.text);

  if (!insert) {
    return false;
  }

  let frag = Fragment.empty;
  for (let i = insert.length - 1; i >= 0; i--) {
    frag = Fragment.from(insert[i].createAndFill(null, frag));
  }

  const tr = view.state.tr.replace($from.pos, $from.pos, new Slice(frag, 0, 0));
  tr.setSelection(TextSelection.near(tr.doc.resolve($from.pos + 1)));

  view.dispatch(tr);
  return false;
};

const buildGapSpacerDecorationSet = ({
  doc,
  t,
  positions,
  focusedPos,
}: {
  doc: ProseMirrorNode;
  t: TFunction;
  positions: GapSpacerPosition[];
  focusedPos: number | null;
}): DecorationSet | null => {
  if (positions.length === 0) {
    return null;
  }

  const decorations: Decoration[] = positions.map(
    ({ pos, collapsed, betweenFloated, needsTopMargin: topMargin }) =>
      createSpacer({
        pos,
        isFocused: focusedPos === pos,
        t,
        collapsed,
        betweenFloated,
        needsTopMargin: topMargin,
      })
  );

  return DecorationSet.create(doc, decorations);
};

export const createSpacer = ({
  pos,
  isFocused = false,
  t,
  collapsed,
  betweenFloated,
  needsTopMargin: topMargin = false,
}: {
  pos: number;
  isFocused?: boolean;
  t: TFunction;
  collapsed: boolean;
  betweenFloated: boolean;
  needsTopMargin?: boolean;
}): Decoration =>
  Decoration.widget(
    pos,
    view => {
      const container = document.createElement('div');
      if (betweenFloated) {
        container.className = styles.betweenFloated;
      }
      const gapSpacerElement = createGapSpacerElement({
        collapsed,
        isFocused,
        tooltipContent: t('GapSpacer_Tooltip'),
        needsTopMargin: topMargin,
        onClick: (event?: Event) => {
          event?.preventDefault();
          event?.stopImmediatePropagation();
        },
        onMouseDown: (event?: Event) => {
          event?.preventDefault();
          event?.stopImmediatePropagation();

          const { state, dispatch } = view;
          const paragraph = state.schema.nodes.PARAGRAPH;
          const tr = state.tr.insert(pos, paragraph.create());
          tr.setSelection(TextSelection.create(tr.doc, pos, pos + 1));
          dispatch(tr);
        },
      });
      container.appendChild(gapSpacerElement);
      return container;
    },
    {
      key: `gapspacer-${pos}-${isFocused ? 'focused' : 'unfocused'}-${
        collapsed ? 'collapsed' : 'expanded'
      }-${betweenFloated ? 'floated' : 'static'}-${topMargin ? 'topMargin' : 'noTopMargin'}`,
    }
  );
