import { UNSTYLED } from './../../ricos-content/index.js';
import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { EditorPlugin } from './../../ricos-types/index.js';
import { createShortcut } from './../../ricos-types/index.js';

import { paragraph } from './extension.js';
import { paragraphConverter } from './paragraph-converter.js';

export const pluginParagraph: EditorPlugin = {
  type: Node_Type.PARAGRAPH,
  pmMarkConverters: [],
  pmNodeConverters: [paragraphConverter],
  shortcuts: [
    createShortcut({
      name: Node_Type.PARAGRAPH,
      description: 'ShortcutsSheet_Formatting_ParagraphFormat',
      keys: { macOs: 'Meta+Alt+0', windows: 'Ctrl+Alt+0' },
      command({ publicCommands }) {
        publicCommands.setBlockType(UNSTYLED);
        return 'continue';
      },
      group: 'ShortcutsSheet_Section_Formatting',
      enabled: true,
      showInShortcutSheet: true,
    }),
  ],
  config: {},
  tiptapExtensions: [paragraph],
};
