import type { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import type { Transaction } from './../../tiptap/pm/state.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import { ReplaceStep } from './../../tiptap/pm/transform.js';
import type { Decoration as PmDecoration } from './../../tiptap/pm/view.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';

import { isInlineTextOnly } from '../transaction-predicates/is-inline-text-only.js';
import { onlyChangesUnrelatedAttrs } from '../transaction-predicates/only-changes-unrelated-attrs.js';

/**
 * Wraps the children of every `targetNodeTypes` textblock in a `<span>`.
 * Used for block types that expose a `backgroundColor` via the Theme API —
 * the color must be applied as an inline-text background, so each inline
 * child needs to live inside its own span.
 *
 * One multi-type plugin instead of one-per-type keeps a single
 * `DecorationSet` for the whole wrap-in-span concern, which PM's view
 * descends once per block on each render.
 *
 * On inline-text-only transactions, only the touched textblock's span
 * decorations are rebuilt — a plain `prev.map(tr.mapping, tr.doc)` can't be
 * used because `DecorationSet.map`'s `assoc = +1/-1` semantics would place
 * newly-inserted characters outside the span.
 */
export const createSpanWrapperDecorationPlugin = (targetNodeTypes: Node_Type[]) => {
  const targetTypeNames: ReadonlySet<string> = new Set(targetNodeTypes);
  const key = new PluginKey<DecorationSet>('span-wrapper');

  return new Plugin<DecorationSet>({
    key,
    state: {
      init: (_config, state) => buildFullSet(state.doc, targetTypeNames),
      apply: (tr, prev) => {
        if (!tr.docChanged) {
          return prev;
        }
        if (isInlineTextOnly(tr)) {
          return rebuildTouchedBlocks(tr, prev, targetTypeNames);
        }
        // Walks children for span emission — reads structure only, no attrs.
        if (onlyChangesUnrelatedAttrs(tr)) {
          return prev;
        }
        return buildFullSet(tr.doc, targetTypeNames);
      },
    },
    props: {
      decorations(state) {
        return key.getState(state);
      },
    },
  });
};

const buildSpanWrappersForBlock = (block: ProseMirrorNode, blockStart: number): PmDecoration[] => {
  const decorations: PmDecoration[] = [];
  block.forEach((childNode, childOffset) => {
    if (childNode.type.name === 'hardBreak') {
      return;
    }
    const childStart = blockStart + childOffset + 1;
    const childEnd = childStart + childNode.nodeSize;
    decorations.push(Decoration.inline(childStart, childEnd, { nodeName: 'span' }));
  });
  return decorations;
};

const buildFullSet = (
  doc: ProseMirrorNode,
  targetTypeNames: ReadonlySet<string>
): DecorationSet => {
  const decorations: PmDecoration[] = [];

  doc.descendants((node, pos) => {
    if (targetTypeNames.has(node.type.name)) {
      decorations.push(...buildSpanWrappersForBlock(node, pos));
      return false;
    }
    // All target types are textblocks; textblocks only contain inline
    // content, so a non-target textblock cannot contain a target. Pruning
    // here avoids descending into every text/mark child of unrelated
    // textblocks.
    if (node.isTextblock) {
      return false;
    }
  });

  return DecorationSet.create(doc, decorations);
};

/**
 * Remap `prev` through `tr.mapping`, then rebuild span decorations for each
 * target-type textblock any step in `tr` touched. Caller must have
 * established (via `isInlineTextOnly`) that no step changes doc structure
 * for any non-touched block.
 *
 * Correctness note: `step.from` lives in the coordinate space of the doc
 * right before this step (`tr.docs[stepIndex]`), not `tr.before`. Resolving
 * `step.from` against `tr.doc` directly would silently be wrong for any
 * 2nd+ step — `tr.mapping.slice(stepIndex).map(step.from)` forwards the
 * position through the remaining steps into `tr.doc`.
 */
const rebuildTouchedBlocks = (
  tr: Transaction,
  prev: DecorationSet,
  targetTypeNames: ReadonlySet<string>
): DecorationSet => {
  let next = prev.map(tr.mapping, tr.doc);

  // A single transaction can have several steps all hitting the same
  // target textblock — only rebuild each block once.
  const rebuiltBlockStarts = new Set<number>();

  tr.steps.forEach((step, stepIndex) => {
    if (!(step instanceof ReplaceStep)) {
      return;
    }

    const finalFrom = tr.mapping.slice(stepIndex).map(step.from);
    const $from = tr.doc.resolve(finalFrom);
    if (!targetTypeNames.has($from.parent.type.name)) {
      return;
    }

    const blockStart = $from.before($from.depth);
    if (rebuiltBlockStarts.has(blockStart)) {
      return;
    }
    rebuiltBlockStarts.add(blockStart);

    const blockEnd = blockStart + $from.parent.nodeSize;
    next = next.remove(next.find(blockStart, blockEnd));
    next = next.add(tr.doc, buildSpanWrappersForBlock($from.parent, blockStart));
  });

  return next;
};
