import React, { Suspense, lazy } from 'react';

import type { TextAlignmentDropdownProps } from './text-alignment-dropdown.js';

const AlignmentPanelController = lazy(() =>
  import('./text-alignment-dropdown.js').then(({ default: TextAlignmentDropdown }) => ({
    default: TextAlignmentDropdown,
  }))
);

const AlignmentPanelComponent = (props: TextAlignmentDropdownProps) => (
  <Suspense fallback={<div style={{ width: 38 }} />}>
    <AlignmentPanelController {...props} />
  </Suspense>
);

export default AlignmentPanelComponent;
