import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
// File copied from https://github.com/ProseMirror/prosemirror-gapcursor/blob/master/src/gapcursor.ts
import type { Node, ResolvedPos } from './../../tiptap/pm/model.js';
import { Slice } from './../../tiptap/pm/model.js';
import { NodeSelection, Selection } from './../../tiptap/pm/state.js';
import type { Mappable } from './../../tiptap/pm/transform.js';

import { isListContainer } from './gap-spacer-nodes.js';

/// Gap cursor selections are represented using this class. Its
/// `$anchor` and `$head` properties both point at the cursor position.
export class GapCursor extends Selection {
  /// Create a gap cursor.
  constructor($pos: ResolvedPos) {
    super($pos, $pos);
  }

  map(doc: Node, mapping: Mappable): Selection {
    const $pos = doc.resolve(mapping.map(this.head));
    return GapCursor.valid($pos) ? new GapCursor($pos) : Selection.near($pos);
  }

  content() {
    return Slice.empty;
  }

  eq(other: Selection): boolean {
    return other instanceof GapCursor && other.head === this.head;
  }

  toJSON(): any {
    return { type: 'gapcursor', pos: this.head };
  }

  /// @internal
  static fromJSON(doc: Node, json: any): GapCursor {
    if (typeof json.pos !== 'number') {
      throw new RangeError('Invalid input for GapCursor.fromJSON');
    }
    return new GapCursor(doc.resolve(json.pos));
  }

  /// @internal
  getBookmark() {
    return new GapBookmark(this.anchor);
  }

  /// @internal
  static hasAdjacentUnwrappedTextNodes($pos: ResolvedPos) {
    const before = $pos.nodeBefore;
    const after = $pos.nodeAfter;
    return (before && before.isText) || (after && after.isText);
  }

  /// @internal
  static valid($pos: ResolvedPos) {
    const parent = $pos.parent;

    if (parent.type.name === Node_Type.LIST_ITEM) {
      return false;
    }

    if (parent.isTextblock || !closedBefore($pos) || !closedAfter($pos)) {
      return false;
    }

    if (GapCursor.hasAdjacentUnwrappedTextNodes($pos)) {
      return false;
    }

    const nodeBefore = $pos.nodeBefore;
    const nodeAfter = $pos.nodeAfter;

    // Don't render a gap spacer between two list containers (any combination
    // of bulleted / ordered / checkbox); lists touching each other should sit
    // flush, the same way they do inside a single list_item.
    if (isListContainer(nodeBefore?.type.name) && isListContainer(nodeAfter?.type.name)) {
      return false;
    }

    if (nodeAfter?.type.name === Node_Type.LAYOUT && nodeAfter?.attrs?.banner?.position === 'TOP') {
      return false;
    }

    // Don't allow gap cursor after bottom-attached layouts
    if (
      nodeBefore?.type.name === Node_Type.LAYOUT &&
      nodeBefore?.attrs?.banner?.position === 'BOTTOM'
    ) {
      return false;
    }

    try {
      const defaultType = parent.contentMatchAt($pos.index())?.defaultType;
      return defaultType && defaultType.isTextblock;
    } catch {
      return false;
    }
  }

  /// @internal
  static findGapCursorFrom($pos: ResolvedPos, dir: number, mustMove = false) {
    // oxlint-disable-next-line no-labels
    search: for (;;) {
      if (!mustMove && GapCursor.valid($pos)) {
        return $pos;
      }
      let pos = $pos.pos,
        next = null;
      // Scan up from this position
      for (let d = $pos.depth; ; d--) {
        const parent = $pos.node(d);
        if (dir > 0 ? $pos.indexAfter(d) < parent.childCount : $pos.index(d) > 0) {
          next = parent.child(dir > 0 ? $pos.indexAfter(d) : $pos.index(d) - 1);
          break;
        } else if (d === 0) {
          return null;
        }
        pos += dir;
        const $cur = $pos.doc.resolve(pos);
        if (GapCursor.valid($cur)) {
          return $cur;
        }
      }

      // And then down into the next node
      for (;;) {
        const inside: Node | null = dir > 0 ? next.firstChild : next.lastChild;
        if (!inside) {
          if (next.isAtom && !next.isText && !NodeSelection.isSelectable(next)) {
            // oxlint-disable-next-line no-param-reassign
            $pos = $pos.doc.resolve(pos + next.nodeSize * dir);
            // oxlint-disable-next-line no-param-reassign
            mustMove = false;
            // oxlint-disable-next-line no-labels
            continue search;
          }
          break;
        }
        next = inside;
        pos += dir;
        const $cur = $pos.doc.resolve(pos);
        if (GapCursor.valid($cur)) {
          return $cur;
        }
      }

      return null;
    }
  }
}

GapCursor.prototype.visible = false;
(GapCursor as any).findFrom = GapCursor.findGapCursorFrom;

Selection.jsonID('gapcursor', GapCursor);

class GapBookmark {
  // oxlint-disable-next-line no-useless-constructor
  constructor(readonly pos: number) {}

  map(mapping: Mappable) {
    return new GapBookmark(mapping.map(this.pos));
  }

  resolve(doc: Node): GapCursor | Selection {
    const $pos = doc.resolve(this.pos);
    return GapCursor.valid($pos) ? new GapCursor($pos) : Selection.near($pos);
  }
}

function closedBefore($pos: ResolvedPos) {
  for (let d = $pos.depth; d >= 0; d--) {
    const index = $pos.index(d),
      parent = $pos.node(d);
    // At the start of this parent, look at next one
    if (index === 0) {
      if (parent.type.spec.allowGapSpacer) {
        return true;
      }
      // If we're at the start of the document root, allow gap spacer
      if (d === 0) {
        return true;
      }
      continue;
    }
    // See if the node before (or its first ancestor) is closed
    for (let before = parent.child(index - 1); ; before = before.lastChild) {
      if (before.childCount === 0 && !before.inlineContent) {
        return true;
      }
      if (before?.type?.spec?.allowGapSpacer) {
        return true;
      }
      if (before.inlineContent) {
        return false;
      }
      if (!before.lastChild) {
        break;
      }
    }
  }
  // Hit start of document
  return false;
}

function shouldPreventGapSpacerAfterNestedList(parent: Node, index: number): boolean {
  return (
    parent.type.name === Node_Type.LIST_ITEM &&
    index > 0 &&
    isListContainer(parent.child(index - 1).type.name)
  );
}

function closedAfter($pos: ResolvedPos) {
  for (let d = $pos.depth; d >= 0; d--) {
    const index = $pos.indexAfter(d),
      parent = $pos.node(d);
    if (index === parent.childCount) {
      if (shouldPreventGapSpacerAfterNestedList(parent, index)) {
        return false;
      }

      if (parent.type?.spec?.allowGapSpacer) {
        return true;
      }

      // Mirror `closedBefore`: at the very end of the document root, allow a
      // gap spacer. The original gap-cursor used `parent.type.spec.isolating`
      // here (which is true for `doc`), but the migration to
      // `allowGapSpacer` (#8658) only ported this fallback into
      // `closedBefore` and left `closedAfter` asymmetric, so trailing edge
      // gap spacers stopped rendering.
      if (d === 0) {
        return true;
      }

      continue;
    }
    for (let after = parent.child(index); ; after = after.firstChild) {
      if (after.childCount === 0 && !after.inlineContent) {
        return true;
      }
      if (after?.type?.spec?.allowGapSpacer) {
        return true;
      }
      if (after.inlineContent) {
        return false;
      }
      if (!after.firstChild) {
        break;
      }
    }
  }
  return false;
}
