import { Node_Type, TextStyle_TextAlignment } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';

import { isInlineTextOnly } from '../transaction-predicates/is-inline-text-only.js';
import { onlyChangesUnrelatedAttrs } from '../transaction-predicates/only-changes-unrelated-attrs.js';

// Reads `attrs.textStyle.textAlignment` on LIST_ITEM. AttrStep operates on
// top-level keys, so any change to `textAlignment` arrives as an AttrStep
// touching `textStyle`.
const RELEVANT_ATTRS: ReadonlySet<string> = new Set(['textStyle']);

/**
 * Sets `list-style-position: inside` (via a data-attribute) on centered
 * list items.
 *
 * Output depends only on `attrs.textStyle.textAlignment` of LIST_ITEM
 * nodes, which inline-text-only edits cannot change.
 */
export const createListStylePositionDecorationPlugin = () => {
  const key = new PluginKey<DecorationSet>('list-style-position');

  return new Plugin<DecorationSet>({
    key,
    state: {
      init: (_config, state) => buildListStylePositionDecorations(state.doc),
      apply: (tr, prev) => {
        if (!tr.docChanged) {
          return prev;
        }
        if (isInlineTextOnly(tr)) {
          return prev.map(tr.mapping, tr.doc);
        }
        if (onlyChangesUnrelatedAttrs(tr, RELEVANT_ATTRS)) {
          return prev;
        }
        return buildListStylePositionDecorations(tr.doc);
      },
    },
    props: {
      decorations(state) {
        return key.getState(state);
      },
    },
  });
};

const buildListStylePositionDecorations = (doc: ProseMirrorNode): DecorationSet => {
  const decorations: Decoration[] = [];

  doc.descendants((node, pos) => {
    // Text blocks (paragraph, heading, blockquote) cannot contain list items,
    // so skipping their subtree avoids visiting every text/mark node.
    // We cannot prune at LIST_ITEM because it may contain nested lists via
    // `listItemSecondChildContent`, and those nested list items still need
    // decorations.
    if (node.isTextblock) {
      return false;
    }

    if (node.type.name !== Node_Type.LIST_ITEM) {
      return;
    }

    if (node.attrs.textStyle.textAlignment === TextStyle_TextAlignment.CENTER) {
      decorations.push(
        Decoration.node(pos, pos + node.nodeSize, {
          'data-list-style-position': 'inside',
        })
      );
    }
  });

  return DecorationSet.create(doc, decorations);
};
