import React, { Suspense, lazy } from 'react';

import type { FontSizeDropdownProps } from './dropdown/font-size-dropdown.js';

const FontSizePanelController = lazy(() =>
  import('./dropdown/font-size-dropdown.js').then(({ default: FontSizeDropdown }) => ({
    default: FontSizeDropdown,
  }))
);

export const FontSizePanelComponent = (props: FontSizeDropdownProps) => (
  <Suspense fallback={<div style={{ width: 38 }} />}>
    <FontSizePanelController {...props} minWidth={38} />
  </Suspense>
);
