import type { PmNodeConverter } from './../../pm-converters/types.js';
import type { Node } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { ListItemChildNode, ListItemNode, ListItemNodeData } from './../../ricos-schema/next-schema/index.js';
import type { PmListItemNode, PmNode } from './../../_shared/pm-node-types.js';

export const listItemConverter: PmNodeConverter = {
  toPm: {
    types: [Node_Type.LIST_ITEM],
    // @ts-expect-error $TSFixMe
    convert: (node: ListItemNode, visit: (node: ListItemNode) => PmNode[]) => {
      const { id = '' } = node || {};

      const listItemChildNode = node?.nodes?.[0];
      const textAlignment =
        listItemChildNode?.type === Node_Type.PARAGRAPH &&
        listItemChildNode?.paragraphData?.textStyle?.textAlignment;

      const result: PmListItemNode = {
        type: Node_Type.LIST_ITEM,
        attrs: {
          ...(textAlignment ? { textStyle: { textAlignment } } : {}),
          id,
          checked: node.listItemData?.checked ?? null,
          animation: node.listItemData?.animation ?? null,
        },
        content: visit(node),
      };

      return result;
    },
  },
  fromPm: {
    types: [Node_Type.LIST_ITEM],
    // @ts-expect-error $TSFixMe
    convert: (node: PmListItemNode, visit: (node: PmListItemNode) => Node[]) => {
      const attributes = node.attrs;
      const { id, checked, animation } = attributes || {};

      const nodes = visit(node) as ListItemChildNode[];

      const listItemData: ListItemNodeData = {
        ...(checked === true ? { checked: true } : {}),
        ...(animation ? { animation } : {}),
      };

      const result: ListItemNode = {
        type: Node_Type.LIST_ITEM,
        id,
        nodes,
        ...(Object.keys(listItemData).length > 0 ? { listItemData } : {}),
      };
      return result;
    },
  },
};
