import type { Transaction } from './../../tiptap/pm/state.js';
import { ReplaceStep } from './../../tiptap/pm/transform.js';

/**
 * ## Guarantees when `isInlineTextOnly(tr)` returns `true`
 *
 * 1. Every step is a {@link ReplaceStep}.
 * 2. Each step's slice contains only inline content (text / inline nodes /
 *    marks). No block nodes are inserted.
 * 3. Each step's `from`/`to` range lies strictly inside a single textblock in
 *    the document that step operates on (`tr.docs[stepIndex]`). The range
 *    never spans a block boundary.
 *
 * ## What this means for consumers
 *
 * - The doc's block structure is invariant across the transaction: no block
 *   is added, removed, split, merged, wrapped, or re-parented. The shape of
 *   the node tree stays identical — only positions shift.
 * - Every block's attributes and neighbours are invariant. Anything keyed on
 *   `$pos.parent`, `$pos.nodeBefore`, `$pos.nodeAfter`, or
 *   `node.attrs.<anything>` stays correct.
 * - Inline marks, text content, and per-text offsets inside the affected
 *   textblocks *do* change. Anything that reads text, marks, or inline
 *   structure must not assume invariance.
 * - `tr.mapping` correctly remaps any cached absolute position into the
 *   post-transaction doc.
 *
 * ## Typing-style transactions this covers
 *
 * Regular keystrokes, deletes, selection-replace with plain text, paste-as-
 * plain-text inside a paragraph, and composition events that land as one or
 * more same-textblock ReplaceSteps.
 *
 * ## What is explicitly *not* covered
 *
 * - Any transaction with an `AddMarkStep` / `RemoveMarkStep`
 *   / `ReplaceAroundStep` / `AttrStep` — those change marks/attrs/structure.
 * - ReplaceSteps whose slice contains a block node (e.g. pasting a paragraph).
 * - ReplaceSteps whose range crosses a block boundary.
 * - Transactions with zero steps (selection-only / scroll / focus).
 */
export const isInlineTextOnly = (tr: Transaction): boolean => {
  if (tr.steps.length === 0) {
    return false;
  }

  return tr.steps.every((step, stepIndex) => {
    if (!(step instanceof ReplaceStep)) {
      return false;
    }

    // Slice must contain only inline content. An empty slice (pure deletion)
    // is fine — it has no descendants.
    let onlyInline = true;
    step.slice.content.descendants(node => {
      if (!node.isInline) {
        onlyInline = false;
        return false;
      }
      return onlyInline;
    });
    if (!onlyInline) {
      return false;
    }

    // `step.from`/`step.to` are positions in the doc *right before this
    // step* (`tr.docs[stepIndex]`), not in `tr.before`. Resolving against
    // the wrong doc silently gives wrong parents for 2nd+ steps of a
    // multi-step transaction.
    const docBeforeStep = tr.docs[stepIndex];
    const $from = docBeforeStep.resolve(step.from);
    const $to = docBeforeStep.resolve(step.to);

    if ($from.parent !== $to.parent) {
      return false;
    }
    if (!$from.parent.isTextblock) {
      return false;
    }

    return true;
  });
};
