export const commonPlugins = (editorProps: EditorProps, pluginOptions: { type: string }[]) => {
  const layoutConfig = pluginOptions.find((config): config is LayoutPluginConfig =>
    ['LAYOUT', 'layout'].includes(config.type)
  );
  const fontSizeConfig = pluginOptions.find(
    (config): config is FontSizePluginConfig => config.type === 'fontSize'
  );
  return [
    pluginBlockquote,
    pluginBold,
    pluginBulletedList,
    pluginCheckboxList,
    pluginFontSize(fontSizeConfig),
    pluginItalic,
    pluginListItem,
    pluginOrderedList,
    pluginParagraph,
    pluginTextAlignment,
    pluginUnderline,
    pluginResizable,
    pluginDraggable,
    pluginUndoRedo,
    pluginTitle,
    pluginHardBreak,
    pluginBreakout,
    pluginTab,
    pluginSelection,
    pluginNotOvertypable,
    pluginGapSpacer,
    unsupportedPlugin,
    pluginStrikethrough,
    pluginSubscript,
    pluginSuperscript,
    pluginLayout(layoutConfig),
    pluginCell(layoutConfig),
    pluginQuickActions(
      (() => {
        const qa = editorProps?.toolbarSettings
          ?.getToolbarSettings?.({})
          ?.find(({ name }) => name === ToolbarType.QUICK_ACTIONS) as
          | {
              placeholder?: string;
              customPlaceholder?: string;
              activateOnFloatingPlusButton?: boolean;
              shouldCreate?: () => any;
            }
          | undefined;
        // The toolbar-settings `placeholder` field maps to the plugin's
        // `customPlaceholder` config — historically these names diverged.
        // Translate `placeholder` only when it's defined; never overwrite a
        // user-supplied `customPlaceholder`.
        if (!qa) {
          return {};
        }
        const { placeholder, ...rest } = qa;
        return placeholder !== undefined ? { ...rest, customPlaceholder: placeholder } : rest;
      })()
    ),
    pluginSpotlight,
  ].filter(isDefined) as EditorPlugin<Record<string, any>>[];
};

export const commonPluginConfig = {
  [INDENT_TYPE]: { isTextSelection, AllSelection },
};
