import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import type { Transaction } from './../../tiptap/pm/state.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import { ReplaceStep } from './../../tiptap/pm/transform.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';
import { getLangDir } from './../../wix-rich-content-common/Utils/rtl-utils.js';

import { isInlineTextOnly } from '../transaction-predicates/is-inline-text-only.js';
import { onlyChangesUnrelatedAttrs } from '../transaction-predicates/only-changes-unrelated-attrs.js';

/**
 * Adds a `dir` attribute to every target-type textblock outside of list
 * items:
 *
 *   dir = content.size > 0 ? 'auto' : emptyNodeDirection
 *
 * A single plugin handles multiple target types (e.g. paragraph + heading)
 * instead of one-per-type — PM's view walks every plugin's `DecorationSet`
 * once per block on each render, so fewer sets means less per-keystroke
 * `forChild` / `mapInner` work.
 */
export const createDirectionAttributeDecorationPlugin = (
  targetNodeTypes: Node_Type | Node_Type[],
  localeContent: string
) => {
  const types = Array.isArray(targetNodeTypes) ? targetNodeTypes : [targetNodeTypes];
  const targetTypeNames: ReadonlySet<string> = new Set(types);
  const emptyNodeDirection = getLangDir(localeContent);

  const key = new PluginKey<DecorationSet>('direction-attribute');

  return new Plugin<DecorationSet>({
    key,
    state: {
      init: (_config, state) =>
        buildDirectionDecorations(state.doc, targetTypeNames, emptyNodeDirection),
      // The decoration value for a target node is
      //   dir = content.size > 0 ? 'auto' : emptyNodeDirection
      // — it only changes when the node crosses the empty ↔ non-empty
      // boundary. For inline-text-only transactions where no target node
      // crosses that boundary, the cached set can be safely mapped through
      // `tr.mapping` (positions shift, attribute values are unchanged).
      apply: (tr, prev) => {
        if (!tr.docChanged) {
          return prev;
        }
        if (canReuseDirectionDecorations(tr, targetTypeNames)) {
          return prev.map(tr.mapping, tr.doc);
        }
        // Decoration value depends only on `node.content.size` (empty ↔
        // non-empty) and node types — neither is touched by attr steps.
        if (onlyChangesUnrelatedAttrs(tr)) {
          return prev;
        }
        return buildDirectionDecorations(tr.doc, targetTypeNames, emptyNodeDirection);
      },
    },
    props: {
      decorations(state) {
        return key.getState(state);
      },
    },
  });
};

const canReuseDirectionDecorations = (
  tr: Transaction,
  targetTypeNames: ReadonlySet<string>
): boolean => {
  if (!isInlineTextOnly(tr)) {
    return false;
  }

  return tr.steps.every((step, stepIndex) => {
    // `isInlineTextOnly` already proves every step is a ReplaceStep confined
    // to a single textblock; the cast below is just for type narrowing.
    if (!(step instanceof ReplaceStep)) {
      return false;
    }

    // `step.from` is in the coordinate space of the doc right before this
    // step (`tr.docs[stepIndex]`), not `tr.before`.
    const docBeforeStep = tr.docs[stepIndex];
    const parent = docBeforeStep.resolve(step.from).parent;

    // Edits to non-target textblocks cannot change any target's decoration
    // value; positional shifts are handled by `tr.mapping`.
    if (!targetTypeNames.has(parent.type.name)) {
      return true;
    }

    const removedSize = step.to - step.from;
    const insertedSize = step.slice.size;
    const newContentSize = parent.content.size - removedSize + insertedSize;

    const wasEmpty = parent.content.size === 0;
    const willBeEmpty = newContentSize === 0;

    return wasEmpty === willBeEmpty;
  });
};

const buildDirectionDecorations = (
  doc: ProseMirrorNode,
  targetTypeNames: ReadonlySet<string>,
  emptyNodeDirection: string
): DecorationSet => {
  const decorations: Decoration[] = [];

  doc.descendants((node, pos) => {
    if (node.type.name === Node_Type.LIST_ITEM) {
      return false;
    }

    if (targetTypeNames.has(node.type.name)) {
      decorations.push(
        Decoration.node(pos, pos + node.nodeSize, {
          dir: node.content.size > 0 ? 'auto' : emptyNodeDirection,
        })
      );
      return false;
    }

    // All target types are textblocks (PARAGRAPH / HEADING / BLOCKQUOTE),
    // and textblocks only contain inline content — so any non-target
    // textblock cannot contain a target. Pruning here avoids descending
    // into every text/mark child of unrelated textblocks.
    if (node.isTextblock) {
      return false;
    }
  });

  return DecorationSet.create(doc, decorations);
};
