import { Strikethrough } from '@wix/wix-ui-icons-common/lazy';

import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { EditorPlugin } from './../../ricos-types/index.js';
import { createShortcut } from './../../ricos-types/index.js';
import { isStrikethroughBlockedByCheckboxListSelection } from './../../_shared/list-checkbox/is-strikethrough-blocked-by-checkbox-list-selection.js';
import { isAlwaysVisible } from './../../_shared/resolvers/is-always-visible.js';
import { isNodeSelected } from './../../_shared/resolvers/is-node-selected.js';
import { isStrikethroughInText } from './../../_shared/resolvers/is-striketrough-in-text.js';

import { TEXT_BUTTON_STRIKETHROUGH } from './data-hooks.js';
import { strikethrough } from './extension.js';
import { strikethroughConverter } from './strikethrough-converter.js';

export const pluginStrikethrough: EditorPlugin = {
  type: Decoration_Type.STRIKETHROUGH,
  config: {},
  pmMarkConverters: [strikethroughConverter],
  pmNodeConverters: [],
  tiptapExtensions: [strikethrough],
  shortcuts: [
    createShortcut({
      name: Decoration_Type.STRIKETHROUGH,
      description: 'ShortcutsSheet_Formatting_Strikethrough',
      keys: { macOs: 'Meta+Shift+X', windows: 'Ctrl+Shift+X' },
      command({ publicCommands }) {
        publicCommands.toggleInlineStyle('strikethrough');
        return 'continue';
      },
      group: 'ShortcutsSheet_Section_Formatting',
      enabled: true,
      showInShortcutSheet: true,
    }),
  ],

  textButtons: [
    {
      id: Decoration_Type.STRIKETHROUGH,
      type: 'toggle',
      presentation: {
        dataHook: TEXT_BUTTON_STRIKETHROUGH,
        tooltip: 'StrikethroughButton_Tooltip',
        icon: Strikethrough,
      },
      attributes: {
        visible: isAlwaysVisible,
        active: isStrikethroughInText,
        disabled: (content, services, editor) =>
          isNodeSelected(content, services, editor) ||
          (editor?.state ? isStrikethroughBlockedByCheckboxListSelection(editor.state) : false),
      },
      command:
        ({ publicCommands }) =>
        () => {
          publicCommands.toggleInlineStyle('strikethrough');
          return true;
        },
    },
  ],
};
