import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type {
  DOMOutputSpec,
  ExtensionProps,
  NodeConfig,
  RicosExtension,
} from './../../ricos-types/index.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';

import { createDirectionAttributeDecorationPlugin } from '../decoration-plugins/direction-attribute.js';
import { createSpanWrapperDecorationPlugin } from '../decoration-plugins/span-wrapper.js';
import { isInlineTextOnly } from '../transaction-predicates/is-inline-text-only.js';
import { onlyChangesUnrelatedAttrs } from '../transaction-predicates/only-changes-unrelated-attrs.js';
import { HEADER_NAMES } from './header-names.js';
import styles from './headings-scss.js';

// `textblock-id` decoration plugin reads `attrs.id` on textblocks.
const TEXTBLOCK_ID_RELEVANT_ATTRS: ReadonlySet<string> = new Set(['id']);

export type Level = 1 | 2 | 3 | 4 | 5 | 6;

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    heading: {
      /**
       * Set a heading node
       */
      setHeading: (attributes: { level: Level }) => ReturnType;
      /**
       * Toggle a heading node
       */
      toggleHeading: (attributes: { level: Level }) => ReturnType;
    };
  }
}

export const heading = createRicosNodeExtension({
  groups: ['no-trailing-node'],
  type: 'html-node',
  name: Node_Type.HEADING,
  reconfigure: (
    config: NodeConfig,
    _extensions: RicosExtension[],
    _props: ExtensionProps,
    settings: Record<string, unknown>,
    services
  ) => ({
    ...config,
    addOptions() {
      return {
        levels: [1, 2, 3, 4, 5, 6],
        ...settings,
      };
    },
    addProseMirrorPlugins() {
      return [
        createTextblockIdDecorationPlugin({
          includeChildren: Boolean(this.options.includeChildren),
        }),
        createSpanWrapperDecorationPlugin([Node_Type.HEADING]),
        createDirectionAttributeDecorationPlugin(Node_Type.HEADING, services.context.localeContent),
      ];
    },
  }),
  createExtensionConfig({ mergeAttributes, textblockTypeInputRule }) {
    return {
      name: this.name,

      content: 'inline*',

      group:
        'block smartBlockCellContent layoutCellContent collapsibleListItemTitleContent collapsibleListItemBodyContent tableCellContent listItemFirstChildContent listItemSecondChildContent',

      defining: true,

      addAttributes() {
        return {
          level: 0,
          textStyle: {
            default: null,
            parseHTML: element => {
              try {
                const attrValue = element.getAttribute('textstyle');
                return attrValue ? JSON.parse(attrValue) : null;
              } catch {
                return null;
              }
            },
          },
          indentation: null,
          renderedLevel: null,
        };
      },

      parseHTML() {
        return this.options.levels.map((level: Level) => ({
          tag: `h${level}`,
          attrs: { level },
        }));
      },

      renderHTML({ node, HTMLAttributes }) {
        const hasLevel = this.options.levels.includes(node.attrs.level);
        const level = hasLevel ? node.attrs.level : this.options.levels[0];
        const hasRenderedLevel = this.options.levels.includes(node.attrs.renderedLevel);
        const tagLevel = hasRenderedLevel ? node.attrs.renderedLevel : level;
        const attrs = mergeAttributes(
          this.options.HTMLAttributes,
          {
            ...HTMLAttributes,
            textStyle: JSON.stringify(HTMLAttributes.textStyle),
          },
          {
            class: styles[`header${HEADER_NAMES[level - 1]}`],
          }
        );

        return [`h${tagLevel}`, attrs, 0] as DOMOutputSpec;
      },

      addCommands() {
        return {
          setHeading:
            attributes =>
            ({ commands }) => {
              if (!this.options.levels.includes(attributes.level)) {
                return false;
              }

              return commands.updateTextNode(this.name, attributes);
            },
          toggleHeading:
            attributes =>
            ({ commands }) => {
              if (!this.options.levels.includes(attributes.level)) {
                return false;
              }

              return commands.toggleTextNode(this.name, Node_Type.PARAGRAPH, attributes);
            },
        };
      },

      addKeyboardShortcuts() {
        return this.options.levels.reduce(
          (items: $TSFixMe, level: Level) => ({
            ...items,

            ...{
              [`Mod-Alt-${level}`]: () => this.editor.commands.toggleHeading({ level }),
            },
          }),
          {}
        );
      },

      addInputRules() {
        return this.options.levels.map((level: Level) => {
          return textblockTypeInputRule({
            find: new RegExp(`^(#{1,${level}})\\s$`),
            type: this.type,
            getAttributes: {
              level,
            },
          });
        });
      },
    };
  },
});

type TextblockIdOptions = {
  // When true, keep descending into children of textblocks that already
  // have an `id` attribute. When false (default), stop at the first match.
  includeChildren?: boolean;
};

// Surfaces every textblock's `attrs.id` as `data-ricos-id` on the rendered
// node. Value depends only on `attrs.id`, which inline-text edits never
// change, so the cached set is reusable across inline-text transactions.
const createTextblockIdDecorationPlugin = ({
  includeChildren = false,
}: TextblockIdOptions = {}) => {
  const key = new PluginKey<DecorationSet>('textblock-id');

  return new Plugin<DecorationSet>({
    key,
    state: {
      init: (_config, state) => buildTextblockIdDecorations(state.doc, includeChildren),
      apply: (tr, prev) => {
        if (!tr.docChanged) {
          return prev;
        }
        if (isInlineTextOnly(tr)) {
          return prev.map(tr.mapping, tr.doc);
        }
        if (onlyChangesUnrelatedAttrs(tr, TEXTBLOCK_ID_RELEVANT_ATTRS)) {
          return prev;
        }
        return buildTextblockIdDecorations(tr.doc, includeChildren);
      },
    },
    props: {
      decorations(state) {
        return key.getState(state);
      },
    },
  });
};

const buildTextblockIdDecorations = (
  doc: ProseMirrorNode,
  includeChildren: boolean
): DecorationSet => {
  const decorations: Decoration[] = [];

  doc.descendants((node, pos) => {
    if (!node.isTextblock || !node.attrs.id) {
      return;
    }

    decorations.push(
      Decoration.node(pos, pos + node.nodeSize, {
        'data-ricos-id': node.attrs.id,
      })
    );

    if (!includeChildren) {
      return false;
    }
  });

  return DecorationSet.create(doc, decorations);
};
