import type { PmMarkConverter } from './../../pm-converters/types.js';
import type { SuperscriptDecoration } from './../../ricos-schema/next-schema/index.js';
import { Decoration_Type } from './../../ricos-schema/next-schema/index.js';

export const superscriptConverter: PmMarkConverter = {
  fromPm: {
    type: Decoration_Type.SUPERSCRIPT,
    convert: mark => {
      const { type: _, attrs } = mark;
      if (typeof attrs?.superscriptData === 'undefined' || attrs.superscriptData) {
        return [{ type: Decoration_Type.SUPERSCRIPT }];
      }

      return [{ type: Decoration_Type.SUPERSCRIPT, ...attrs }];
    },
  },
  toPm: {
    type: Decoration_Type.SUPERSCRIPT,
    convert: decoration => {
      const { type: _, ...data } = decoration as SuperscriptDecoration;
      if (typeof data.superscriptData === 'undefined') {
        return {
          type: Decoration_Type.SUPERSCRIPT,
          attrs: { superscriptData: true },
        };
      }
      return {
        type: Decoration_Type.SUPERSCRIPT,
        attrs: { ...data },
      };
    },
  },
};
