import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { DOMOutputSpec } from './../../ricos-types/index.js';
import { createRicosMarkExtension } from './../../plugin-commons/index.js';
import type { TiptapAdapterServices } from './../../tiptap-editor/initialize-tiptap-adapter.js';

import type { FontSizeCommonConfig } from './types.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    fontSize: {
      /**
       * Set a font mark
       */
      setFontSize: (size: number) => ReturnType;
    };
  }
}

export const fontSize = (config?: FontSizeCommonConfig) =>
  createRicosMarkExtension<{ services: TiptapAdapterServices }>({
    type: 'mark',
    groups: [],
    name: Decoration_Type.FONT_SIZE,
    reconfigure: (config, extensions, ricosProps, settings, services) => {
      return {
        ...config,
        addOptions: () => {
          return {
            services,
          };
        },
      };
    },
    createExtensionConfig({ mergeAttributes }) {
      return {
        name: this.name,
        addAttributes() {
          return { unit: 'PX', value: null };
        },

        renderHTML({ HTMLAttributes }) {
          const fontSize =
            config?.overrideInlineFontSize?.(
              HTMLAttributes.value,
              HTMLAttributes.unit?.toLowerCase()
            ) ?? `${HTMLAttributes.value}${HTMLAttributes.unit?.toLowerCase()}`;

          const htmlAttrs = {
            style: `font-size: ${fontSize}`,
            'data-font-size': HTMLAttributes.value,
          };
          return ['span', mergeAttributes(htmlAttrs), 0] as DOMOutputSpec;
        },
        parseHTML() {
          // Like in draft we parse only internal copy/pasted fontSize values
          return [
            {
              tag: 'span',
              getAttrs: (element: HTMLElement) => {
                const attribute = element.attributes.getNamedItem('data-font-size');
                if (!isValidSizeValue(attribute?.value)) {
                  return false;
                }
                return {
                  value: Math.min(Math.max(1, Number(attribute?.value)), 900),
                  unit: 'PX',
                };
              },
            },
          ];
        },
        addCommands() {
          return {
            setFontSize:
              (size: number) =>
              ({ commands }) => {
                if (!isValidSizeValue(size)) {
                  return false;
                }

                return commands.setMark(this.name, {
                  value: size,
                  unit: 'PX',
                });
              },
          };
        },
      };
    },
  });

const isValidSizeValue = (size: unknown): boolean => {
  const n = Number(size);
  return Number.isInteger(n) && n > 0 && n <= 900;
};
