import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type {
  ExtensionProps,
  Group,
  RicosExtension,
  RicosExtensionConfig,
} from './../../ricos-types/index.js';
import { includesGroup } from './../../ricos-types/tiptap.js';
import { createRicosFunctionalExtension } from './../../plugin-commons/index.js';
import type { TiptapAdapterServices } from './../../tiptap-editor/initialize-tiptap-adapter.js';

import { ResizerHOC, createResizerHoc } from './react-resizer.js';

const isResizableGroup = (group: Group): group is Extract<Group, { group: 'resizable' }> =>
  typeof group === 'object' && group?.group === 'resizable';

export const resizable = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'ricos-resizable',
  reconfigure(
    config: RicosExtensionConfig,
    extensions: RicosExtension[],
    _ricosProps: ExtensionProps,
    _settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) {
    const types = extensions
      .filter(extension => !(services.context.isMobile && extension.name === Node_Type.IMAGE))
      .filter(extension => includesGroup(extension.groups, 'resizable'))
      .map(({ name }) => name);

    const defaultHoc = ResizerHOC;

    return {
      ...config,
      priority: 80,
      addNodeHoc: () => {
        return {
          nodeTypes: types,
          getNodeHoc: extension => {
            const group = extension.groups.find(isResizableGroup);
            return group ? createResizerHoc(group.options) : defaultHoc;
          },
          priority: 80,
        };
      },
    };
  },
  createExtensionConfig() {
    return {
      name: this.name,
    };
  },
});
