import type { Decoration } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { DOMOutputSpec } from './../../ricos-types/index.js';
import { isMarkActive } from './../../tiptap/index.js';
import { markInputRule, markPasteRule } from './../../tiptap/core/index.js';
import { createRicosMarkExtension } from './../../plugin-commons/index.js';
import { getStylesDecorationBySelectedNode } from './../../tiptap-extensions/index.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    italic: {
      /**
       * Set an italic mark
       */
      setItalic: () => ReturnType;
      /**
       * Toggle an italic mark
       */
      toggleItalic: () => ReturnType;
      /**
       * Unset an italic mark
       */
      unsetItalic: () => ReturnType;
    };
  }
}

const starInputRegex = /(?:^|\s)((?:\*)((?:[^*]+))(?:\*))$/;
const starPasteRegex = /(?:^|\s)((?:\*)((?:[^*]+))(?:\*))/g;
const underscoreInputRegex = /(?:^|\s)((?:_)((?:[^_]+))(?:_))$/;
const underscorePasteRegex = /(?:^|\s)((?:_)((?:[^_]+))(?:_))/g;

const name = Decoration_Type.ITALIC;

export const italic = createRicosMarkExtension({
  type: 'mark',
  groups: [],
  name,
  reconfigure(config, _extensions, _ricosProps, _settings, services) {
    return {
      ...config,
      addCommands() {
        return {
          setItalic:
            () =>
            ({ commands }) => {
              return commands.setMark(this.name);
            },
          toggleItalic:
            () =>
            ({ commands, state }) => {
              const decoration: Decoration | undefined = getStylesDecorationBySelectedNode(name, {
                state,
                styles: services.styles,
                pmConverters: services.converters,
              });
              const hasItalicInStyle = decoration && decoration.italicData === true;
              const hasItalicInMark = isMarkActive(state, this.name, { italicData: true });

              return commands.toggleMark(this.name, {
                italicData: !!(hasItalicInMark || !hasItalicInStyle),
              });
            },
          unsetItalic:
            () =>
            ({ commands }) => {
              return commands.unsetMark(this.name);
            },
        };
      },
    };
  },
  createExtensionConfig() {
    return {
      name,
      addOptions() {
        return {
          HTMLAttributes: {},
        };
      },

      addAttributes() {
        return {
          italicData: {
            default: true,
          },
        };
      },

      parseHTML() {
        return [
          {
            tag: 'em',
          },
          {
            tag: 'i',
            getAttrs: node => (node as HTMLElement).style.fontStyle !== 'normal' && null,
          },
          {
            style: 'font-style=italic',
          },
        ];
      },

      renderHTML({ HTMLAttributes }) {
        const { italicData } = HTMLAttributes;
        return [
          'em',
          { style: `font-style: ${italicData ? 'italic' : 'normal'}` },
          0,
        ] as DOMOutputSpec;
      },

      addKeyboardShortcuts() {
        return {
          'Mod-i': () => this.editor.commands.toggleItalic(),
        };
      },

      addInputRules() {
        return [
          markInputRule({
            find: starInputRegex,
            type: this.type,
          }),
          markInputRule({
            find: underscoreInputRegex,
            type: this.type,
          }),
        ];
      },

      addPasteRules() {
        return [
          markPasteRule({
            find: starPasteRegex,
            type: this.type,
          }),
          markPasteRule({
            find: underscorePasteRegex,
            type: this.type,
          }),
        ];
      },
    };
  },
});
