import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { EditorPlugin } from './../../ricos-types/index.js';
import { createShortcut } from './../../ricos-types/index.js';

import { superscript } from './extension.js';
import { superscriptConverter } from './superscript-converter.js';

export const pluginSuperscript: EditorPlugin = {
  type: Decoration_Type.SUPERSCRIPT,
  config: {},
  pmNodeConverters: [],
  pmMarkConverters: [superscriptConverter],
  tiptapExtensions: [superscript],
  shortcuts: [
    createShortcut({
      name: Decoration_Type.SUPERSCRIPT,
      description: 'ShortcutsSheet_Formatting_Superscript',
      keys: { macOs: 'Meta+.', windows: 'Ctrl+.' },
      command({ publicCommands }) {
        publicCommands.toggleInlineStyle('superscript');
        return 'continue';
      },
      group: 'ShortcutsSheet_Section_Formatting',
      enabled: true,
      showInShortcutSheet: true,
    }),
  ],
};
