import { TIPTAP_FIGURE_TYPE } from './../../ricos-content/index.js';
import type { Node as NodeOld } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { TOP_LEVEL_NODES } from './../../_shared/top-level-nodes.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';
import { createRicosFunctionalExtension } from './../../plugin-commons/index.js';

export const breakout = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'breakout',
  reconfigure(config, _extensions, ricosProps, _settings, services) {
    const breakoutRule = ricosProps.breakoutRule;
    return {
      ...config,
      ...(breakoutRule && {
        addProseMirrorPlugins() {
          return [
            new Plugin({
              key: new PluginKey('breakout'),
              props: {
                decorations(state) {
                  const decorations: Decoration[] = [];

                  const applyBreakoutToNode = (node: typeof state.doc.firstChild, pos: number) => {
                    if (!node) {
                      return;
                    }

                    const ricosNode = services.converters.fromPmNode(node.toJSON());
                    if (!ricosNode) {
                      return;
                    }

                    const breakoutType = breakoutRule({
                      node: ricosNode as NodeOld,
                    });

                    // Here is the exception where breakout applies not only to the root node (FIGURE),
                    // but also to the descendant (IMAGE|VIDEO) node.
                    // This is made in order to override Resizer HOC width which is applied on IMAGE container.
                    if (breakoutType === 'fullWidth' && node.type.name === TIPTAP_FIGURE_TYPE) {
                      node.descendants((childNode, childPos) => {
                        if (childNode.type.spec.group?.includes('figureFirstChildContent')) {
                          const childPosInDoc = childPos + pos + 1;
                          decorations.push(
                            Decoration.node(childPosInDoc, childPosInDoc + childNode.nodeSize, {
                              'data-breakout': breakoutType,
                            })
                          );
                        }
                      });
                    }

                    decorations.push(
                      Decoration.node(pos, pos + node.nodeSize, { 'data-breakout': breakoutType })
                    );
                  };

                  // Walk through wrapper nodes (CARD → CARD_CONTENT/CARD_FOOTER → …)
                  // until we reach actual content blocks, then apply breakout to them.
                  const applyBreakoutToContentBlocks = (node: PmNode, pos: number) => {
                    if ((TOP_LEVEL_NODES as readonly string[]).includes(node.type.name)) {
                      node.forEach((childNode, childOffset) => {
                        const childPos = pos + 1 + childOffset;
                        applyBreakoutToContentBlocks(childNode, childPos);
                      });
                      return;
                    }
                    applyBreakoutToNode(node, pos);
                  };

                  state.doc.forEach((node, pos) => {
                    applyBreakoutToContentBlocks(node, pos);
                  });
                  return DecorationSet.create(state.doc, decorations);
                },
              },
            }),
          ];
        },
      }),
    };
  },
  createExtensionConfig() {
    return {
      name: this.name,
      priority: 3,
    };
  },
});
