import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { EditorPlugin } from './../../ricos-types/index.js';
import { createShortcut } from './../../ricos-types/index.js';

import { subscript } from './extension.js';
import { subscriptConverter } from './subscript-converter.js';

export const pluginSubscript: EditorPlugin = {
  type: Decoration_Type.SUBSCRIPT,
  config: {},
  pmNodeConverters: [],
  pmMarkConverters: [subscriptConverter],
  tiptapExtensions: [subscript],
  shortcuts: [
    createShortcut({
      name: Decoration_Type.SUBSCRIPT,
      description: 'ShortcutsSheet_Formatting_Subscript',
      keys: { macOs: 'Meta+,', windows: 'Ctrl+,' },
      command({ publicCommands, event }) {
        event?.preventDefault();
        publicCommands.toggleInlineStyle('subscript');
        return 'continue';
      },
      group: 'ShortcutsSheet_Section_Formatting',
      enabled: true,
      showInShortcutSheet: true,
    }),
  ],
};
