import type { PublicCommands, TextBlockType } from './../../ricos-types/index.js';

import { TitleIcon, TitleOneIcon, TitleTwoIcon } from './icons/index.js';

const titleStateMap = {
  unstyled: {
    icon: TitleIcon,
    action: 'header-two',
  },
  'header-two': {
    icon: TitleOneIcon,
    action: 'header-three',
  },
  'header-three': {
    icon: TitleTwoIcon,
    action: 'unstyled',
  },
};

const getCurrentTitleState = (publicCommands: PublicCommands) => {
  const selectedHeading = publicCommands.getCurrentHeading() as keyof typeof titleStateMap;
  return titleStateMap[selectedHeading] || titleStateMap.unstyled;
};

export const getTitleIcon = ({ publicCommands }: { publicCommands: PublicCommands }) => {
  const currentTitleState = getCurrentTitleState(publicCommands);
  return currentTitleState.icon;
};

export const getTitleOnClick = (publicCommands: PublicCommands) => {
  const currentTitleState = getCurrentTitleState(publicCommands);
  const currentTitleAction = currentTitleState.action as TextBlockType;
  return () => publicCommands.setBlockType(currentTitleAction);
};
