import type { EditorPlugin } from './../../ricos-types/index.js';

import { getTipTapExtensions } from './tiptap/extensions.js';
import type { QuickActionsEditorConfig } from './types.js';
import { QUICK_ACTIONS } from './types.js';

export const pluginQuickActions = (
  config: QuickActionsEditorConfig
): EditorPlugin<QuickActionsEditorConfig> | undefined => {
  return {
    config: config || {},
    type: QUICK_ACTIONS,
    tiptapExtensions:
      config?.shouldCreate?.()?.desktop === false ? [] : getTipTapExtensions(config),
  };
};
