import type { PmNodeConverter, PmNodeJson } from './../../pm-converters/types.js';
import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { CheckboxListData } from './../../ricos-schema/next-schema/index.js';
import type { CheckboxListNode, ListItemNode } from './../../ricos-types/index.js';

const checkboxListDataDefaults = { indentation: 0, offset: 0 } as const;

export const checkboxListConverter: PmNodeConverter = {
  toPm: {
    types: [Node_Type.CHECKBOX_LIST],
    // @ts-expect-error $TSFixMe
    convert: (node: CheckboxListNode, visit: (node: CheckboxListNode) => PmNodeJson[]) => {
      const dataWithDefaults: CheckboxListData = {
        indentation: node.checkboxListData?.indentation ?? checkboxListDataDefaults.indentation,
        offset: node.checkboxListData?.offset ?? checkboxListDataDefaults.offset,
      };

      return {
        type: Node_Type.CHECKBOX_LIST,
        attrs: {
          ...dataWithDefaults,
          id: node.id,
          animation: node.checkboxListData?.animation ?? null,
        },
        content: visit(node),
      };
    },
  },
  fromPm: {
    types: [Node_Type.CHECKBOX_LIST],
    // @ts-expect-error $TSFixMe
    convert: (node: PmNodeJson, visit: (node: PmNodeJson) => ListItemNode[]) => {
      const { attrs = {} } = node;
      const {
        id,
        indentation = checkboxListDataDefaults.indentation,
        offset = checkboxListDataDefaults.offset,
        animation,
      } = attrs as {
        id?: string;
        indentation?: number;
        offset?: number;
        animation?: CheckboxListData['animation'];
      };

      const checkboxListData: CheckboxListData = {
        ...(indentation !== checkboxListDataDefaults.indentation ? { indentation } : {}),
        ...(offset !== checkboxListDataDefaults.offset ? { offset } : {}),
        ...(animation ? { animation } : {}),
      };

      return {
        type: Node_Type.CHECKBOX_LIST,
        id,
        nodes: visit(node),
        checkboxListData,
      };
    },
  },
};
