import type { PmMarkConverter } from './../../pm-converters/types.js';
import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

export const italicConverter: PmMarkConverter = {
  fromPm: {
    type: Decoration_Type.ITALIC,
    convert: mark => {
      const { type: _, attrs } = mark;
      return [{ type: Decoration_Type.ITALIC, ...attrs }];
    },
  },
  toPm: {
    type: Decoration_Type.ITALIC,
    convert: decoration => {
      const { type: _, ...data } = decoration;
      return {
        type: Decoration_Type.ITALIC,
        attrs: { ...data },
      };
    },
  },
};
